// Used for hashing stable ids, aka node package names that are not part of the client GOM.
function FNV1a64(text) {
  const prime = 0x100000001b3n;
  let hash = 0xcbf29ce484222325n;
  text = text.toUpperCase();
  for (let i = 0, il = text.length; i < il; i += 1) {
    hash ^= BigInt(text.charCodeAt(i));
    hash *= prime;
    hash = BigInt.asUintN(64, hash);
  }
  return String(hash);
}

// Used for hashing HSL script and method names.
function FNV1a32Dec(text) {
  const prime = 0x01000193n;
  let hash = 0x811c9dc5n;
  text = text.toUpperCase();
  for (let i = 0, il = text.length; i < il; i += 1) {
    hash ^= BigInt(text.charCodeAt(i));
    hash *= prime;
    hash = BigInt.asUintN(32, hash);
  }
  return hash;
}
function FNV1a32(text) {
  return FNV1a32Dec(text).toString(16).padStart(8, '0');
}

